{'acquirer': [{'quote': 'On December 10, 2025, Diamond Hill Investment Group, Inc. (referred to as “Diamond Hill”), First Eagle Investment Management, LLC (referred to as “First Eagle”) and Soar Christopher Holdings, Inc., a wholly-owned subsidiary of First Eagle (referred to as “Merger Sub”), entered into an Agreement and Plan of Merger that provides for the acquisition of Diamond Hill by First Eagle', 'location': 'PREM14A, shareholder letter'}], 'target': [{'quote': 'entered into an Agreement and Plan of Merger that provides for the acquisition of Diamond Hill by First Eagle', 'location': 'PREM14A, shareholder letter'}, {'quote': 'Diamond Hill Investment Group, Inc. (referred to as “Diamond Hill”)', 'location': 'PREM14A, shareholder letter'}], 'consideration_type': [{'quote': 'At the effective time, each share of Diamond Hill common stock issued and outstanding immediately prior to the effective time, including Diamond Hill Restricted Shares, (other than excluded shares and dissenting shares) will be converted into the right to receive the merger consideration of $175.00 in cash, without interest and subject to deduction for any required withholding tax.', 'location': 'PREM14A, The Merger (Proposal 1)—Merger Consideration, page 30'}], 'cash_consideration': [{'quote': 'each share of Diamond Hill common stock issued and outstanding immediately prior to the effective time, including Diamond Hill Restricted Shares, (other than excluded shares and dissenting shares) will be converted into the right to receive the merger consideration of $175.00 in cash, without interest and subject to deduction for any required withholding tax.', 'location': 'PREM14A, The Merger (Proposal 1)—Merger Consideration, page 30'}, {'quote': 'Unless otherwise specifically indicated, all references to “dollars” and “$” will be deemed references to the lawful money of the United States of America.', 'location': 'Annex A—Merger Agreement, Section 1.02, page A-14'}], 'stock_exchange_ratio': [{'quote': 'each Company Common Share (including each Company Restricted Share, subject to Section 2.05(a)) outstanding immediately prior to the Effective Time will automatically be converted into the right to receive $175.00 in cash without interest (the “Merger Consideration”)', 'location': 'Annex A—Merger Agreement, Section 2.02(a), page A-15'}], 'shareholder_vote_date': [], 'closing_conditions': [{'quote': 'The obligations of the Company, Parent and Merger Sub to consummate the Merger are subject to the satisfaction of the following conditions:
(a) the Company Shareholder Approval shall have been obtained in accordance with the OGCL;
(b) no Order issued by any court of competent jurisdiction or other Governmental Authority, or Applicable Law prohibiting, rendering illegal or permanently enjoining the consummation of the Merger shall be in effect; and', 'location': 'Annex A—Merger Agreement, Section 9.01, page A-66'}, {'quote': '(c) any applicable waiting period (including any extension thereof and any timing agreement with a Governmental Authority) under the HSR Act relating to the Merger shall have expired or been terminated.', 'location': 'Annex A—Merger Agreement, Section 9.01, page A-67'}, {'quote': 'The obligations of Parent and Merger Sub to consummate the Merger are subject to the satisfaction of the following additional conditions:
(a) (i) the Company shall have performed and complied with in all material respects all of the covenants, obligations and agreements hereunder required to be performed or complied with by it prior to the Closing, (ii) the representations and warranties of the Company contained in Section 4.01(a) (Corporate Existence and Power), Section 4.02 (Corporate Authorization), Section 4.04(a) (Non-Contravention), Section 4.05(a)-(c) (Capitalization), Section 4.25 (Finders’ Fees), Section 4.26 (Opinion of Financial Advisor) and Section 4.27 (Antitakeover Statutes)', 'location': 'Annex A—Merger Agreement, Section 9.02, page A-67'}, {'quote': '(b) since the date of this Agreement, no Company Material Adverse Effect shall have occurred and be continuing', 'location': 'Annex A—Merger Agreement, Section 9.02, page A-67'}, {'quote': '(c) the Client Consent Percentage shall be no less than 78%', 'location': 'Annex A—Merger Agreement, Section 9.02, page A-67'}, {'quote': 'The obligation of the Company to consummate the Merger is subject to the satisfaction of the following additional conditions: (a) each of Parent and Merger Sub shall have performed and complied with in all material respects all of the covenants, obligations and agreements hereunder required to be performed or complied with by it prior to the Closing, (b) the representations and warranties of Parent and Merger Sub', 'location': 'Annex A—Merger Agreement, Section 9.03, page A-67'}], 'event_status': [{'quote': 'On December 10, 2025, Diamond Hill Investment Group, Inc. (referred to as “Diamond Hill”), First Eagle Investment Management, LLC (referred to as “First Eagle”) and Soar Christopher Holdings, Inc., a wholly-owned subsidiary of First Eagle (referred to as “Merger Sub”), entered into an Agreement and Plan of Merger', 'location': 'PREM14A, shareholder letter'}, {'quote': 'First Eagle and Diamond Hill are working to complete the merger as soon as practicable and currently expect the merger to be completed by the third quarter of 2026, subject to the satisfaction or, to the extent permitted, waiver of customary closing conditions', 'location': 'PREM14A, The Merger and Merger Agreement—Expected Timing of the Merger, page 6'}], 'security_description': [{'quote': 'common stock, without par value, of Diamond Hill (the “Diamond Hill common stock”)', 'location': 'PREM14A, shareholder letter'}, {'quote': 'Diamond Hill Investment Group, Inc. (referred to as “Diamond Hill”)', 'location': 'PREM14A, shareholder letter'}], 'effective_date': [{'quote': 'The Merger will become effective at such time as the Certificate of Merger is duly filed with the Secretary of State of the State of Ohio (or at such later time as may be specified in the Certificate of Merger in accordance with the applicable provisions of the OGCL) (the “Effective Time”).', 'location': 'Annex A—Merger Agreement, Section 2.01(c), page A-15'}], 'available_options': [{'quote': 'each Company Common Share (including each Company Restricted Share, subject to Section 2.05(a)) outstanding immediately prior to the Effective Time will automatically be converted into the right to receive $175.00 in cash without interest (the “Merger Consideration”), subject to deduction for any required withholding Tax.', 'location': 'Annex A—Merger Agreement, Section 2.02(a), page A-15'}], 'default_option': [{'quote': 'each Company Common Share (including each Company Restricted Share, subject to Section 2.05(a)) outstanding immediately prior to the Effective Time will automatically be converted into the right to receive $175.00 in cash without interest (the “Merger Consideration”), subject to deduction for any required withholding Tax.', 'location': 'Annex A—Merger Agreement, Section 2.02(a), page A-15'}], 'election_deadline': []}

{'acquirer': [{'quote': 'Merger Sub will merge with and into Ace Green, whereupon the separate corporate existence of Merger Sub will cease and Ace Green will be the surviving company and continue in existence as a wholly owned subsidiary of Athena', 'location': 'S-4/A, letter to Athena stockholders'}, {'quote': '“Athena” means Athena Technology Acquisition Corp. II, a Delaware corporation.', 'location': 'S-4/A, Frequently Used Terms'}], 'target': [{'quote': 'Ace Green Recycling, Inc. a Delaware corporation (“Ace Green”)', 'location': 'S-4/A, letter to Athena stockholders'}], 'consideration_type': [{'quote': 'each share of Ace Green Common Stock issued and outstanding immediately prior to the Effective Time (but excluding any (x) shares of Ace Green Common Stock held by a holder who is entitled to demand and has properly exercised appraisal rights for such shares in accordance with Section 262 of the DGCL and (y) shares of Ace Green Common Stock held by Ace Green as treasury stock) will be cancelled and converted into the right to receive (1) a number of shares of Athena Class A Common Stock (rounded up to the nearest whole share) equal to the quotient of (a) the Aggregate Merger Consideration divided by (b) the number of shares of Ace Green Common Stock outstanding immediately prior to the Closing on a fully diluted basis and (2) a pro rata share of the Earnout Shares', 'location': 'S-4/A, Questions and Answers About the Business Combination, page ix'}, {'quote': 'The rights to the Earnout Shares and/or Sponsor Earnout Shares (i) are solely contractual rights, (ii) will not be evidenced by a certificate, do not constitute securities or other instruments and are not readily marketable', 'location': 'S-4/A, Annex A, Section 1.7(g), page A-5'}], 'cash_consideration': [{'quote': 'each Company Share (other than any Excluded Shares and Dissenting Shares) that is issued and outstanding immediately prior to the Merger Effective Time shall thereupon be converted into, and the holder of such Company Share shall be entitled to in exchange, the right to receive (i) a pro rata portion of any Earnout Shares that SPAC is obligated to issue in accordance with Section 1.6(g) and (ii) the Per Share Merger Consideration.', 'location': 'S-4/A, Annex A, Section 1.6(b), page A-3'}, {'quote': '“Per Share Merger Consideration” means a number of fully paid, validly issued and nonassessable SPAC Shares equal to the Exchange Ratio', 'location': 'S-4/A, Annex A, Article XII, page A-61'}], 'stock_exchange_ratio': [{'quote': '“Exchange Ratio” means a number equal to the quotient of (a) the quotient of (i) $250,000,000 divided by (ii) $10.10, divided by (b) the number of shares of Ace Green Fully Diluted Capital Stock.', 'location': 'S-4/A, Frequently Used Terms, page vi'}, {'quote': 'each share of Ace Green Common Stock issued and outstanding immediately prior to the Effective Time (but excluding any (x) shares of Ace Green Common Stock held by a holder who is entitled to demand and has properly exercised appraisal rights for such shares in accordance with Section 262 of the DGCL and (y) shares of Ace Green Common Stock held by Ace Green as treasury stock) will be cancelled and converted into the right to receive (1) a number of shares of Athena Class A Common Stock (rounded up to the nearest whole share) equal to the quotient of (a) the Aggregate Merger Consideration divided by (b) the number of shares of Ace Green Common Stock outstanding immediately prior to the Closing on a fully diluted basis and (2) a pro rata share of the Earnout Shares', 'location': 'S-4/A, Questions and Answers About the Business Combination, page ix'}], 'shareholder_vote_date': [{'quote': 'At the Athena special meeting, which will be held on , 2026, at , Eastern Time, via live webcast at , Athena will ask its stockholders to approve and adopt the Merger Agreement and the Business Combination', 'location': 'S-4/A, letter to Athena stockholders'}, {'quote': 'The Merger Agreement provides that Ace Green must obtain and deliver such written consent to Athena as promptly as reasonably possible, and in any event within 15 days after, the SEC declares the Registration Statement effective.', 'location': 'S-4/A, The Merger Agreement — Ace Green Stockholder Approvals, page 75'}], 'closing_conditions': [{'quote': 'The obligations of each of Athena, Merger Sub, and Ace Green to consummate the Business Combination are subject to the satisfaction or waiver (where legally permissible) at or prior to the Closing of the following conditions:
• Athena’s stockholders having approved and adopted the Merger Agreement, the Merger and the other transactions comprising the Business Combination, as well as certain related matters;
• Ace Green obtaining any required approvals of its stockholders in connection with the Merger Agreement;
• the absence of any law or governmental order or other action that would have the effect of making the Business Combination illegal or otherwise prohibiting, restraining or imposing any condition on the consummation of the Business Combination;
• Athena’s initial listing application with Nasdaq in connection with the Business Combination having been conditionally approved and, immediately following the effective time of the Merger, Athena shall satisfy any applicable initial listing requirements of Nasdaq, and Athena shall not have received any notice of non-compliance therewith, and the Athena Common Stock and the Athena Warrants shall have been approved for listing on Nasdaq;
• the Registration Statement having been declared effective in accordance with the provisions of the Securities Act, no stop order having been issued by the SEC that remains in effect with respect to the Registration Statement, and no proceeding seeking such a stop order having been threatened or initiated by the SEC and not withdrawn;
• all applicable waiting periods under the HSR Act with respect to the Business Combination having expired or been terminated and all government consents necessary to consummate Business Combination having been obtained; and
• the aggregate amount of the PIPE Investment and cash remaining in the Trust Account following redemptions of shares of Athena Common Stock in connection with the Merger being at least $7,500,000.', 'location': 'S-4/A, The Merger Agreement — Conditions to Closing of the Merger Agreement — Mutual Conditions, page 76'}, {'quote': 'The obligation of Athena and Merger Sub to consummate the Business Combination is further subject to the satisfaction or waiver of the following additional conditions:
• certain fundamental representations and warranties of Athena and Merger Sub being true and correct in all respects on and as of the date of the Merger Agreement and the Closing Date, except for the fundamental representations made as of an earlier date or time, which need be true and correct only as of such earlier date or time, other than de minimis inaccuracies;
• the other representations of Ace Green being true and correct on and as of the date of the Merger Agreement and the Closing Date (except to the extent that any such representation and warranty expressly speaks as of a particular date time, in which case such representation and warranty shall be true and correct as of such particular date) except for any failure of any such representation and warranty to be so true and correct (without giving effect to any materiality, material adverse effect or other similar qualifier contained therein) that, individually or in the aggregate, have not had and would not reasonably be expected to have a material adverse effect on Ace Green or on its ability to consummate the Business Combination;
• Ace Green having performed in all material respects all of its obligations and complied in all material respects with all of its agreements and covenants under the Merger Agreement to be performed or complied with by it on or prior to the Closing Date;
• Ace Green having delivered to Athena a certificate dated as of the Closing Date, signed by an officer of Ace Green, certifying as to the satisfaction of the above conditions;
• no Material Adverse Effect (as defined in the Merger Agreement) shall have occurred with respect to Ace Green that is continuing and uncured;
• the Transaction Documents required to be executed by Ace Green according to the Merger Agreement at or prior to the Closing Date shall have been executed and delivered to Athena; and
• the Ace Expense Cap not having been exceeded or, to the extent exceeded, Ace Green’s stockholders having borne or repaid any amount in excess of the Ace Expense Cap.', 'location': 'S-4/A, The Merger Agreement — Conditions to Closing of the Merger Agreement — Additional Conditions to Athena and Merger Sub’s Obligations to Close, page 77'}, {'quote': 'The obligation of Ace Green to consummate the Business Combination is further subject to the satisfaction or waiver of the following additional conditions:
• certain fundamental representations and warranties of Athena set forth in the Merger Agreement being true and correct in all respects on and as of the date of the Merger Agreement and the Closing Date, except for the fundamental representations made as of an earlier date or time, which need be true and correct only as of such earlier date or time, other than de minimis inaccuracies;
• the other representations and warranties of Athena and Merger Sub set forth in the Merger Agreement being true and correct on and as of the date of the Merger Agreement and the Closing Date (except to the extent that any such representation and warranty expressly speaks as of a particular date, in which case such representation and warranty shall be true and correct as of such particular date) except for any failure
of any such representation and warranty to be so true and correct (without giving effect to any materiality, material adverse effect or other similar qualifier contained therein) that, individually or in the aggregate, have not had and would not reasonably be expected to have a material adverse effect on Athena or on the ability of Athena or Merger Sub to consummate the Business Combination;
• Athena and Merger Sub having performed in all material respects all of their respective obligations and complied in all material respects with all of their respective agreements and covenants under the Merger Agreement to be performed or complied with by it on or prior to the Closing Date;
• Athena having delivered to Ace Green a certificate dated as of the Closing Date, signed by an officer of Athena, certifying as to the satisfaction of the above conditions;
• no Material Adverse Effect (as defined in the Merger Agreement) having occurred with respect to Athena that is continuing and uncured;
• Athena having made all necessary and appropriate arrangements with the trustee to have all of the funds held in the Trust Account disbursed to Athena on the Closing Date, and all such funds released from the Trust Account shall be available to New Ace Green;
• Athena having provided the Public Stockholders with the opportunity to make redemption elections with respect to their Public Shares pursuant to their redemption rights;
• the Transaction Documents required to be executed by Athena and Merger Sub according to the Merger Agreement at or prior to the Closing Date having been executed and delivered to Ace Green;
• Athena’s certificate of incorporation having been amended and restated in its entirety in substantially the form attached as an exhibit to the Merger Agreement and become effective;
• the Athena Expense Cap not having been exceeded or, to the extent exceeded, the Sponsor having borne or repaid any amount in excess of the Athena Expense Cap;
• Athena having received a written waiver of any deferred IPO fees owed to Citigroup Global Markets Inc.; and
• Athena having entered into binding written agreements with the holders of any working capital loans (to the extent not included within the Athena Expense Cap) to convert the unpaid amounts to equity immediately prior to Closing, such that the equity dilution will be borne by either the Sponsor or Athena’s stockholders, but not Ace Green stockholders.', 'location': 'S-4/A, The Merger Agreement — Conditions to Closing of the Merger Agreement — Additional Conditions to Ace Green’s Obligations to Close, pages 77–78'}], 'event_status': [{'quote': 'On December 4, 2024, Athena, Project Atlas Merger Sub Inc., a Delaware corporation and a direct, wholly owned subsidiary of Athena (“Merger Sub”), and Ace Green Recycling, Inc. a Delaware corporation (“Ace Green”), entered into a Business Combination Agreement (as may be amended and/or amended and restated, the “Merger Agreement”), pursuant to which Merger Sub will merge (the “Merger”) with and into Ace Green', 'location': 'S-4/A, letter to Athena stockholders'}, {'quote': 'The information in this preliminary proxy statement/prospectus is not complete and may be changed. The securities described herein may not be sold until the registration statement filed with the U.S. Securities and Exchange Commission is declared effective.', 'location': 'S-4/A, preliminary proxy statement/prospectus'}], 'security_description': [{'quote': '“Ace Green Common Stock” means the shares of common stock of Ace Green, par value $0.0001 per share.', 'location': 'S-4/A, Frequently Used Terms, page iv'}, {'quote': '“Ace Green” means Ace Green Recycling, Inc., a Delaware corporation.', 'location': 'S-4/A, Frequently Used Terms, page iv'}], 'effective_date': [{'quote': 'The Merger shall become effective at the time when the Certificate of Merger has been duly filed with the Secretary of State of the State of Delaware or at such later time as may be agreed by SPAC and Merger Sub (with the prior written consent of the Company) in writing and specified in the Certificate of Merger (the “Merger Effective Time”).', 'location': 'S-4/A, Annex A, Section 1.2, page A-2'}], 'available_options': [{'quote': 'each Company Share (other than any Excluded Shares and Dissenting Shares) that is issued and outstanding immediately prior to the Merger Effective Time shall thereupon be converted into, and the holder of such Company Share shall be entitled to in exchange, the right to receive (i) a pro rata portion of any Earnout Shares that SPAC is obligated to issue in accordance with Section 1.6(g) and (ii) the Per Share Merger Consideration.', 'location': 'S-4/A, Annex A, Section 1.6(b), page A-3'}], 'default_option': [{'quote': 'each Company Share (other than any Excluded Shares and Dissenting Shares) that is issued and outstanding immediately prior to the Merger Effective Time shall thereupon be converted into, and the holder of such Company Share shall be entitled to in exchange, the right to receive (i) a pro rata portion of any Earnout Shares that SPAC is obligated to issue in accordance with Section 1.6(g) and (ii) the Per Share Merger Consideration.', 'location': 'S-4/A, Annex A, Section 1.6(b), page A-3'}], 'election_deadline': []}
